          m.Regs.Set(R8.D, m.Regs.Get R8.E)
        )
      | 0xF6 ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FF6] <> 0x45uy then failwithf "self-modifying code at 0x7FF6"
          m.Fetch()
          m.Regs.Set(R8.B, m.Regs.Get R8.L)
        )
      | 0xF7 ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FF7] <> 0x52uy then failwithf "self-modifying code at 0x7FF7"
          m.Fetch()
          m.Regs.Set(R8.D, m.Regs.Get R8.D)
        )
      | 0xF8 ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FF8] <> 0x56uy then failwithf "self-modifying code at 0x7FF8"
          m.Fetch()
          m.Regs.SetWz(m.Regs.Get R16.HL)
          m.Regs.Set(R8.D, m.Read(m.Regs.Wz()))
        )
      | 0xF9 ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FF9] <> 0x45uy then failwithf "self-modifying code at 0x7FF9"
          m.Fetch()
          m.Regs.Set(R8.B, m.Regs.Get R8.L)
        )
      | 0xFA ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FFA] <> 0x44uy then failwithf "self-modifying code at 0x7FFA"
          m.Fetch()
          m.Regs.Set(R8.B, m.Regs.Get R8.H)
        )
      | 0xFB ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FFB] <> 0x00uy then failwithf "self-modifying code at 0x7FFB"
          m.Fetch()
        )
      | 0xFC ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FFC] <> 0x00uy then failwithf "self-modifying code at 0x7FFC"
          m.Fetch()
        )
      | 0xFD ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FFD] <> 0x00uy then failwithf "self-modifying code at 0x7FFD"
          m.Fetch()
        )
      | 0xFE ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FFE] <> 0x00uy then failwithf "self-modifying code at 0x7FFE"
          m.Fetch()
        )
      | 0xFF ->
        (fun (m: Machine) ->
          if m.Memory.[0x7FFF] <> 0x00uy then failwithf "self-modifying code at 0x7FFF"
          m.Fetch()
        )
      | _ -> (fun (m: Machine) -> failwithf "no code at 0x%04X" (0x7F00 + i))
    )
