  let step (m: Machine) : unit =
    match pageTable.[m.Regs.Pc() >>> 8] with
    | Some arr -> arr.[m.Regs.Pc() &&& 0xFF] m
    | None -> failwithf "execution reached non-code page (pc=%04X)" (m.Regs.Pc())
  /// Install the generated step into Machine (called by Jetpac's constructor).
  let EnsureInstalled () =
    Machine.GeneratedStep <- step
